mapper.select:

SELECT COUNT(1)
FROM ipv4_reputation_profile
WHERE current_score < #{scoreThreshold}


SELECT COUNT(1)
FROM ipv6_reputation_profile
WHERE current_score < #{scoreThreshold}


SELECT ip
FROM ipv4_reputation_profile
WHERE current_score < #{scoreThreshold}
ORDER BY ip
LIMIT #{limit}
OFFSET #{offset}


SELECT ip
FROM ipv6_reputation_profile
WHERE current_score < #{scoreThreshold}
ORDER BY ip
LIMIT #{limit}
OFFSET #{offset}

SELECT ip AS "ip", current_score AS "currentScore", country AS "country", region AS "region", city AS "city", asn AS "asn", provider_name AS "providerName", ip_type AS "ipType", is_datacenter AS "datacenter", is_vpn AS "vpn", is_proxy AS "proxy", is_tor AS "tor", source_provider AS "sourceProvider", last_seen_at AS "lastSeenAt", queried_at AS "queriedAt", expires_at AS "expiresAt" FROM ipv4_reputation_profile
UPPER(country) = #{country}
AND current_score >= #{minScore}
AND current_score < #{maxScoreExclusive}
AND LOWER(ip) LIKE LOWER(#{ipQueryPattern})
ORDER BY current_score ASC, is_tor DESC, is_proxy DESC, is_vpn DESC, is_datacenter DESC, last_seen_at DESC NULLS LAST, queried_at DESC NULLS LAST, ip ASC

SELECT ip AS "ip", current_score AS "currentScore", country AS "country", region AS "region", city AS "city", asn AS "asn", provider_name AS "providerName", ip_type AS "ipType", is_datacenter AS "datacenter", is_vpn AS "vpn", is_proxy AS "proxy", is_tor AS "tor", source_provider AS "sourceProvider", last_seen_at AS "lastSeenAt", queried_at AS "queriedAt", expires_at AS "expiresAt" FROM ipv6_reputation_profile
UPPER(country) = #{country}
AND current_score >= #{minScore}
AND current_score < #{maxScoreExclusive}
AND LOWER(ip) LIKE LOWER(#{ipQueryPattern})
ORDER BY current_score ASC, is_tor DESC, is_proxy DESC, is_vpn DESC, is_datacenter DESC, last_seen_at DESC NULLS LAST, queried_at DESC NULLS LAST, ip ASC
